pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor, address other) public {
        vm.assume(actor != address(0));
        vm.assume(other != address(0));
        vm.assume(actor != other);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint120).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok);

        vm.prank(actor);
        try c.withdraw() { } catch { }

        uint256 contractBalance = address(c).balance;
        uint256 recordedSum = c.balances(actor) + c.balances(other);

        assertTrue(contractBalance >= recordedSum);
    }
}
